const $=s=>document.querySelector(s);
const state={user:null,users:[],statuses:null,view:'dashboard',tasks:[],office:[],activities:[],summary:null,day:new Date().toLocaleDateString('en-CA'),detail:null,detailTab:'timeline',filter:'',devFilter:'all',qaFilter:'all',typeFilter:'all',dailyEmail:'',categoryFilter:'all',privateItems:[],boardSort:'priority',local:false};
const escapeHTML=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e=escapeHTML;
const dateFmt=x=>x?new Date(x+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'}):'—';
const timeFmt=x=>x?new Date(x).toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}):'—';
const initial=s=>(s||'?').split(/[@ ._-]/).filter(Boolean).slice(0,2).map(s=>s[0]).join('').toUpperCase();
const who=email=>state.users.find(u=>u.email===email)?.display_name||email?.split('@')[0]||'—';
const role=()=>state.user?.role||'';
const canDev=()=>(role()==='admin'&&!isBoss())||(canWrite()&&state.user?.groups?.includes('Engineering'));
const canWrite=()=>!!state.user&&!isBoss();
const isBoss=()=>!!state.user?.groups?.includes('Management');
const canManage=()=>role()==='admin'&&!isBoss();
const canQA=()=>(role()==='admin'&&!isBoss())||(canWrite()&&state.user?.groups?.includes('QA'));
const api=async(path,options={})=>{
  const headers={...(options.headers||{})};if(options.body&&!((options.body) instanceof FormData))headers['content-type']='application/json';
  if(options.method&&options.method!=='GET')headers['x-work-tracker']='1';
  if(state.local)headers['x-dev-user']=$('#demo-user').value||'zoey@demo.local';
  const r=await fetch('/api'+path,{...options,headers});const contentType=r.headers.get('content-type')||'';
  const d=contentType.includes('json')?await r.json():{error:await r.text()};if(!r.ok)throw new Error(d.error||'Request failed');return d;
};
const showToast=(msg,failed=false)=>{const t=$('#toast');t.textContent=msg;t.style.background=failed?'#904949':'#2e3a45';t.classList.remove('hidden');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>t.classList.add('hidden'),3100)};
const busy=async fn=>{try{await fn();}catch(err){showToast(err.message||String(err),true);console.error(err)}};
const option=(items,sel)=>items.map(v=>`<option value="${e(v)}" ${String(sel)===String(v)?'selected':''}>${e(v)}</option>`).join('');
const badge=(v)=>{const x=String(v||'—');let c='gray';if(/Passed|Completed|Production|Closed|Approved|Merged/.test(x))c='green';if(/Changes Required|Unable|Urgent|Blocked/.test(x))c='red';if(/Review|Stage|PR|Testing|Progress|Partial/.test(x))c='blue';if(/Waiting|Need Explanation|No Visible|Retest|On Hold/.test(x))c='amber';return `<span class="badge ${c}">${e(x)}</span>`};
const heading=(eyebrow,title,sub,actions='')=>`<div class="page-heading"><div><div class="eyebrow">${e(eyebrow)}</div><h1 class="page-title">${e(title)}</h1><div class="subtitle">${e(sub)}</div></div><div class="heading-actions">${actions}</div></div>`;
const empty=(title,sub)=>`<div class="empty"><strong>${e(title)}</strong>${e(sub)}</div>`;
const taskTitle=t=>`<div class="title-cell" data-open="${e(t.id)}">${e(t.title)}<div class="muted" style="font-weight:400;margin-top:5px;font-size:10px">${e(t.category||'General')} · ${e(t.type)}${t.parent_task_id?' · '+e(state.tasks.find(p=>p.id===t.parent_task_id)?.title||'Parent task'):''}</div></div>`;
function setView(v){if(v==='mywork')v='daily';if(v==='engineering')v='board';if(v==='history'&&!canManage())return;state.view=v;$('#crumb').textContent={dashboard:'Dashboard',board:'Engineering Board',daily:'Daily Work',engineering:'Engineering Daily Activity',mywork:'My Work',history:'Activity History',releases:'Version Control',team:'Team Access'}[v]||v;document.querySelectorAll('#nav [data-view]').forEach(el=>el.classList.toggle('active',el.dataset.view===v));render()}
async function load(){
  const me=await api('/me');state.user=me.user;state.statuses=me.statuses;state.local=me.devMode;if(state.local)$('#demo-user').value=state.user.email;if(canDev())await api('/releases/ensure',{method:'POST'});
  const [users,tasks,office,activities,summary]=await Promise.all([api('/users'),api('/tasks'),api('/office'),(canManage()?api('/activity'):Promise.resolve({activities:[]})),api('/summary?date='+state.day)]);
  state.users=users.users;state.tasks=tasks.tasks;state.office=office.logs;state.activities=activities.activities;state.summary=summary;
  $('#account-profile').hidden=false;$('#login-entry').hidden=true;$('#nav').hidden=false;$('.top-actions').hidden=false;$('#current-user').textContent=state.user.display_name||who(state.user.email);$('#current-role').textContent=isBoss()?'Manager':(state.user.groups||[]).join(', ');$('#avatar').textContent=initial(who(state.user.email));$('#team-nav').hidden=!canManage();
  $('#demo-user').hidden=!state.local;$('#history-nav').hidden=!canManage();
  if(state.local)$('#demo-user').value=state.user.email;
  render();
}
async function reload(){const [users,tasks,office,activities,summary]=await Promise.all([api('/users'),api('/tasks'),api('/office'),(canManage()?api('/activity'):Promise.resolve({activities:[]})),api('/summary?date='+state.day)]);state.users=users.users;state.tasks=tasks.tasks;state.office=office.logs;state.activities=activities.activities;state.summary=summary;render();if(state.detail)await openDetail(state.detail)}
function render(){if(!state.user)return;const el=$('#content');if(state.view==='dashboard'){if(isBoss()){el.innerHTML=heading('TEAM OVERVIEW','Manager overview','Daily work, engineering progress and upcoming releases.',`<input class="date-input" type="date" value="${state.day}" data-day>`)+'<div id="manager-results">Loading team overview…</div>';busy(loadManagerOverview)}else el.innerHTML=renderDashboard();}if(state.view==='board'){el.innerHTML=renderBoard();busy(loadBoardActivity);}if(['daily','mywork','engineering'].includes(state.view))el.innerHTML=renderDaily();if(state.view==='history')el.innerHTML=renderHistory();if(state.view==='team')el.innerHTML=renderTeam();if(state.view==='releases'){el.innerHTML=heading('ENGINEERING','Version Control','Weekly Wednesday releases: delivered changes and upcoming plans.')+'<div id="release-results">Loading versions…</div>';busy(loadReleases)}}
function renderDashboard(){
  const s=state.summary||{counts:{total:0,needQa:0,needEngineering:0,production:0},attention:[],daily:[],office_counts:[],today_activity:[]};const cs=s.counts;
  const people=new Map();for(const item of [...s.daily.map(x=>({...x,type:'eng'})),...s.office_counts.map(x=>({...x,type:'office'}))]){if(!people.has(item.email))people.set(item.email,{eng:0,office:0});people.get(item.email)[item.type]+=item.count}
  const summaryRows=[...people.entries()].map(([email,a])=>`<tr><td><div class="row-flex"><span class="mini-avatar">${e(initial(who(email)))}</span><b class="focus-num">${e(who(email))}</b></div></td><td>${a.eng}</td><td>${a.office}</td><td>${a.eng+a.office}</td></tr>`).join('');
  const waiting=s.attention.map(t=>`<div class="list-row"><div class="list-main"><div class="list-title" data-open="${e(t.id)}">${e(t.title)}</div><div class="list-meta">${badge(t.development_status)} &nbsp; ${badge(t.qa_status)}<span style="margin-left:9px">Next: ${e(who(t.next_action_owner))}</span></div></div><span class="list-right">${e(t.last_qa_action?dateFmt(t.last_qa_action):'Not tested')}</span></div>`).join('');
  const priorityTasks=[...state.tasks].filter(t=>t.development_status!=='Closed').sort((a,b)=>priorityRank(a.priority)-priorityRank(b.priority)||a.sort_order-b.sort_order).slice(0,8);
  const priorities=priorityTasks.map(t=>`<div class="list-row"><div class="list-main"><div class="list-title" data-open="${e(t.id)}">${e(t.title)}</div><div class="list-meta">${badge(t.priority)} &nbsp; ${badge(t.development_status)} <span style="margin-left:8px">Next: ${e(who(t.next_action_owner))}</span></div></div></div>`).join('');
  const activityRows=(s.today_activity||[]).map(a=>`<tr><td>${e(who(a.person))}</td><td>${a.private?badge('Private work'):badge(a.category)}</td><td>${a.task_id?`<div class="title-cell" data-open="${e(a.task_id)}">${e(a.title)}</div>`:e(a.title)}</td><td>${badge(a.result)}</td><td class="activity-note" title="${e(a.notes||'')}">${e(a.notes||'—')}</td></tr>`).join('');
  return heading(isBoss()?'TEAM OVERVIEW':'PERSONAL OVERVIEW','Daily activity',isBoss()?'See what everyone worked on today before reviewing priorities.':'Your daily activity is private to you and the boss.',`<input class="date-input" type="date" value="${state.day}" data-day>`)+
   `<section class="card priority-today"><div class="card-head"><div><h2 class="card-title">Today’s activity</h2><p class="card-desc">Dated shared-task work and private records visible to your role</p></div><button class="btn tiny" data-view="daily">All activity ↗</button></div><div class="table-wrap"><table class="table"><thead><tr><th>PERSON</th><th>ACTIVITY</th><th>WORK / TASK</th><th>RESULT</th><th>DETAILS</th></tr></thead><tbody>${activityRows||`<tr><td colspan="5">${empty('No activity logged yet','New activity and office entries appear here automatically.')}</td></tr>`}</tbody></table></div></section>`+
   `<div class="grid2 dashboard-next"><section class="card"><div class="card-head"><div><h2 class="card-title">Needs attention</h2><p class="card-desc">Issues waiting for a response or retest</p></div><button class="btn tiny" data-view="board">View board ↗</button></div><div class="card-body">${waiting||empty('All caught up','No tasks currently flagged for attention.')}</div></section><section class="card"><div class="card-head"><div><h2 class="card-title">Priority queue</h2><p class="card-desc">Urgent and high priority tasks first</p></div><button class="btn tiny" data-view="board">View board ↗</button></div><div class="card-body">${priorities||empty('Nothing in the queue','All tasks are closed.')}</div></section></div>`+
   `<div class="stats lower-stats"><div class="stat"><div class="caption">Active tasks</div><div class="value">${cs.total}</div><div class="sub">Across engineering projects</div></div><div class="stat"><div class="caption">Waiting for QA</div><div class="value">${cs.needQa}</div><div class="sub">On Stage / ready to test</div></div><div class="stat"><div class="caption">Needs engineering</div><div class="value">${cs.needEngineering}</div><div class="sub">QA feedback and questions</div></div><div class="stat"><div class="caption">On production</div><div class="value">${cs.production}</div><div class="sub">Deployed tasks</div></div></div>`+
   `<section class="card"><div class="card-head"><div><h2 class="card-title">Activity by team member</h2><p class="card-desc">Counts of dated work entries for ${e(state.day)}</p></div><button class="btn tiny" data-view="daily">View log ↗</button></div><div class="table-wrap"><table class="table"><thead><tr><th>TEAM MEMBER</th><th>SHARED TASK WORK</th><th>PRIVATE WORK</th><th>TOTAL</th></tr></thead><tbody>${summaryRows||`<tr><td colspan="4">${empty('No entries','Records appear as team members log work.')}</td></tr>`}</tbody></table></div></section>`+
   `<div class="section-gap"></div><div class="report-intro">${canManage()?'<button class="btn tiny" id="download-export">Export permitted data</button> &nbsp;':''}Engineering and QA work appear automatically in the daily record. General task comments are not counted as work.</div>`;
}
const priorityRank=p=>({Urgent:0,High:1,Medium:2,Low:3})[p]??4;

function renderBoard(){
 const q=state.filter.toLowerCase();const matches=state.tasks.filter(t=>(!q||[t.title,t.description,t.project,t.category,state.tasks.find(p=>p.id===t.parent_task_id)?.title,t.assignee,t.next_action_owner].join(' ').toLowerCase().includes(q))&&(state.categoryFilter==='all'||t.category===state.categoryFilter)&&(state.typeFilter==='all'||t.type===state.typeFilter)&&(state.devFilter==='all'||t.development_status===state.devFilter)&&(state.qaFilter==='all'||t.qa_status===state.qaFilter));
 const compare=(a,b)=>(a.development_status==='Closed')-(b.development_status==='Closed')|| (state.boardSort==='manual'?(a.sort_order-b.sort_order||priorityRank(a.priority)-priorityRank(b.priority)):state.boardSort==='recent'?String(b.updated_at).localeCompare(String(a.updated_at)):(priorityRank(a.priority)-priorityRank(b.priority)||a.sort_order-b.sort_order))||a.title.localeCompare(b.title);matches.sort(compare);
 return heading('SHARED WORKSPACE','Engineering Board','Track requests, bugs, PRs, deployments and QA independently.',canWrite()?`<button class="btn primary" data-modal="task">+ New task / request</button>`:'')+
 `<div class="filters"><input type="search" class="search" id="task-search" placeholder="Search tasks, projects or assignees" value="${e(state.filter)}"/><select class="select" id="category-filter"><option value="all">All categories</option>${option([...new Set([...(state.statuses.categories||[]),...state.tasks.map(t=>t.category)])].filter(Boolean),state.categoryFilter)}</select><select class="select" id="type-filter"><option value="all">All types</option>${option(state.statuses.types,state.typeFilter)}</select><select class="select" id="dev-filter"><option value="all">All development stages</option>${option(state.statuses.development,state.devFilter)}</select><select class="select" id="qa-filter"><option value="all">All QA results</option>${option(state.statuses.qa,state.qaFilter)}</select><select class="select" id="board-sort" aria-label="Sort tasks">${option(['Priority first','Manual order','Recently updated'],state.boardSort==='manual'?'Manual order':state.boardSort==='recent'?'Recently updated':'Priority first')}</select></div>`+
 `<section class="card board-card"><div class="table-wrap"><table class="table"><thead><tr><th>TASK</th><th>PRIORITY</th><th>ORDER</th><th>DEVELOPMENT</th><th>QA RESULT</th><th>ASSIGNED TO</th><th>NEXT ACTION</th><th>LAST ENGINEER</th><th>LAST QA</th></tr></thead><tbody>${matches.map(t=>`<tr><td>${taskTitle(t)}</td><td>${badge(t.priority)}</td><td>${e(t.sort_order)}</td><td>${badge(t.development_status)}</td><td>${badge(t.qa_status)}</td><td>${e(who(t.assignee))}</td><td>${e(who(t.next_action_owner))}</td><td>${e(dateFmt(t.last_engineer_action))}</td><td>${e(dateFmt(t.last_qa_action))}</td></tr>`).join('')||`<tr><td colspan="9">${empty('No matching tasks','Create a new request or adjust the filters.')}</td></tr>`}</tbody></table></div></section><div class="footer-note">${matches.length} of ${state.tasks.length} tasks · Priority first by default · Set manual order in task details</div><div class="section-gap"></div><section class="card"><div class="card-head"><div><h2 class="card-title">Daily Engineering Activity</h2></div><input type="date" class="date-input" value="${state.day}" data-day></div><div id="board-daily-results">Loading activity…</div></section>`;
}
function renderDaily(){
 return heading('PERSONAL WORKSPACE','Daily Work',isBoss()?'Team activities and ongoing private projects.':'Your ongoing projects, small tasks and daily activities.',`<input type="date" class="date-input" value="${state.day}" data-day> ${canWrite()?'<button class="btn" data-private-new>+ Project / task</button> <button class="btn primary" data-modal="office">+ Activity</button>':''}`)+
 (isBoss()?`<div class="filters"><label>Team member</label><select class="select" id="daily-email"><option value="">Everyone</option>${state.users.filter(u=>u.enabled).map(u=>`<option value="${e(u.email)}" ${state.dailyEmail===u.email?'selected':''}>${e(who(u.email))}</option>`).join('')}</select></div>`:'')+
 '<div id="private-work-results"></div><div class="section-gap"></div><div id="daily-results">Loading activities…</div>';
}
async function loadDaily(){const day=state.day,email=state.dailyEmail,params=new URLSearchParams({date:day});if(isBoss()&&email)params.set('email',email);const [d,p]=await Promise.all([api('/daily?'+params),api('/private-work'+(isBoss()&&email?'?email='+encodeURIComponent(email):''))]);if(state.view!=='daily'||day!==state.day||email!==state.dailyEmail)return;state.privateItems=p.items;renderPrivateWork();
 const rows=[...d.activities.map(a=>({dt:a.created_at,person:a.actor_email,kind:a.action_type,title:a.task_title,result:a.result,notes:a.notes,task_id:a.task_id})),...d.office.map(a=>({id:a.id,dt:a.created_at,person:a.owner_email,kind:'Private activity',title:a.title,result:a.status,notes:a.details,item:a.work_item_id}))].sort((a,b)=>b.dt.localeCompare(a.dt));const body=$('#daily-results');if(!body)return;
 body.innerHTML=`<section class="card"><div class="card-head"><h2 class="card-title">Activities · ${e(dateFmt(day))}</h2></div><div class="table-wrap"><table class="table"><thead><tr><th>PERSON</th><th>WORK / TASK</th><th>STATUS / ACTIVITY</th><th>DETAILS</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td>${e(who(r.person))}</td><td>${r.task_id?`<div class="title-cell" data-open="${e(r.task_id)}">${e(r.title)}</div>`:e(r.title)}${r.item?`<div class="muted-note">${e(state.privateItems.find(i=>i.id===r.item)?.title||'Private project / task')}</div>`:''}</td><td>${badge(r.result||r.kind)}</td><td class="work-notes">${e(r.notes||'—')}</td><td>${r.id&&canWrite()&&r.person===state.user.email?`<button class="btn tiny" data-office-edit="${e(r.id)}">Edit</button> <button class="btn tiny" data-office-delete="${e(r.id)}">Delete</button>`:''}</td></tr>`).join('')||'<tr><td colspan="5">No activity logged for this date.</td></tr>'}</tbody></table></div></section>`;
}
function renderHistory(){
 if(!canManage())return empty('Access denied','Activity History is Admin only.');const rows=state.activities;return heading('AUDITABLE RECORDS','Activity History','Append-only work log. Original actions and timestamps are never overwritten.',`<input type="search" class="search" id="history-search" placeholder="Filter by task, person or result" value="${e(state.filter)}">`)+
 `<section class="card board-card"><div class="table-wrap"><table class="table"><thead><tr><th>WORK DATE</th><th>RECORDED AT</th><th>PERSON</th><th>ACTION</th><th>TASK</th><th>RESULT / NOTES</th></tr></thead><tbody>${rows.filter(a=>!state.filter||[a.task_title,a.actor_email,a.result,a.notes].join(' ').toLowerCase().includes(state.filter.toLowerCase())).map(a=>`<tr><td>${e(dateFmt(a.activity_date))}</td><td>${e(timeFmt(a.created_at))}</td><td>${e(who(a.actor_email))}</td><td>${badge(a.action_type)}</td><td><div class="title-cell" data-open="${e(a.task_id)}">${e(a.task_title)}</div></td><td title="${e(a.notes)}" style="max-width:290px"><strong style="font-size:11px;color:#43515d">${e(a.result)}</strong><div class="muted" style="font-size:11px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${e(a.notes)}</div></td></tr>`).join('')||`<tr><td colspan="6">${empty('No history','Activity entries appear here automatically.')}</td></tr>`}</tbody></table></div></section>`;
}
function renderTeam(){if(!canManage())return empty('Access denied','Only Admin can manage members.');return heading('PERMISSIONS','Team Access','Admin manages team accounts. Private daily entries remain visible only to the owner and boss.',`<button class="btn primary" data-modal="user">+ Add member</button>`)+`<div class="report-intro">Create an email account, assign its system role and work groups, then set its password.</div><section class="card"><div class="table-wrap"><table class="table"><thead><tr><th>NAME</th><th>EMAIL</th><th>ROLE</th><th>ACCOUNT</th></tr></thead><tbody>${state.users.map(u=>`<tr><td><span class="mini-avatar">${e(initial(who(u.email)))}</span><b class="focus-num">${e(u.display_name||'—')}</b></td><td>${e(u.email)}</td><td>${badge(u.role)} ${e(JSON.parse(u.groups_json||'[]').map(g=>g==='Management'?'Manager':g).join(' · '))} </td><td>${u.enabled?badge('Active'):badge('Disabled')} <button class="btn" data-edit-user="${e(u.email)}">Edit</button></td></tr>`).join('')}</tbody></table></div></section>`;
}
async function openDetail(taskId){
 const d=await api('/tasks/'+taskId);state.detail=taskId;state.detailTab='timeline';$('#panel-shade').classList.remove('hidden');$('#detail-panel').classList.remove('hidden');renderDetail(d);
}
function closeDetail(){state.detail=null;$('#panel-shade').classList.add('hidden');$('#detail-panel').classList.add('hidden')}
const inputSelect=(label,key,value,opts,enabled=true)=>`<div class="field"><label>${e(label)}</label><select class="task-field" data-key="${e(key)}" ${enabled?'':'disabled'}>${option(opts,value)}</select></div>`;
const inputText=(label,key,value,enabled=true)=>`<div class="field"><label>${e(label)}</label><input type="text" class="task-field" data-key="${e(key)}" value="${e(value)}" ${enabled?'':'disabled'}/></div>`;
function renderDetail(d){state.detailData=d;const t=d.task;
 const activity=d.activities.map(a=>`<div class="timeline-item"><div class="timeline-top"><div class="timeline-actor">${e(who(a.actor_email))}<span class="timeline-kind">${e(a.action_type)}</span></div><div class="timeline-date">${dateFmt(a.activity_date)}</div></div><div class="timeline-result">${e(a.result)}</div>${a.notes?`<div class="timeline-result">${e(a.notes)}</div>`:''}<div class="list-meta" style="margin-top:7px">${e(a.environment||'')} · recorded ${e(timeFmt(a.created_at))}${a.github_pr_url?` · <a target="_blank" rel="noopener noreferrer" href="${e(a.github_pr_url)}">PR ↗</a>`:''}</div></div>`).join('');
 const discussion=d.comments.map(c=>`<div class="comment-box"><div class="head">${e(who(c.actor_email))}<span>${timeFmt(c.created_at)}</span></div><div class="text">${e(c.body)}</div></div>`).join('');
 $('#detail-content').innerHTML=`<div class="panel-header"><div class="panel-kicker">TASK DETAILS · ${e(t.type.toUpperCase())}</div><button class="close" data-close="detail" aria-label="Close">×</button></div><div class="panel-body"><div class="eyebrow">${e(t.category||'General')} / ${e(t.priority)} PRIORITY</div><h2 class="detail-heading">${e(t.title)}</h2>${t.parent_task_id?`<div class="muted-note">Parent task: <span class="title-cell" data-open="${e(t.parent_task_id)}">${e(state.tasks.find(p=>p.id===t.parent_task_id)?.title||'Parent task')}</span></div>`:''}<p class="detail-description">${e(t.description||'No description added yet.')}</p><div class="detail-fields">${inputSelect('Development status','development_status',t.development_status,state.statuses.development,canDev())}${inputSelect('QA result','qa_status',t.qa_status,state.statuses.qa,canQA())}${inputSelect('Priority','priority',t.priority,state.statuses.priorities,canQA())}<div class="field"><label>Manual order (smaller = first)</label><input class="task-field" data-key="sort_order" type="number" min="1" max="1000000" step="1" value="${e(t.sort_order)}" ${canManage()?'':'disabled'}></div>${inputSelect('Category','category',t.category||'General',[...new Set([...(state.statuses.categories||[]),t.category])].filter(Boolean),canQA()||canDev())}${parentTaskSelect(t)}${inputSelect('Type','type',t.type,[...new Set([...state.statuses.types,t.type])],canQA())}${inputText('Assignee','assignee',t.assignee,canQA())}${inputText('Next action owner','next_action_owner',t.next_action_owner,canQA())}${inputText('GitHub PR URL','github_pr_url',t.github_pr_url,canDev())}<div class="field"><label>Last engineer activity</label><div class="code-line">${e(dateFmt(state.tasks.find(x=>x.id===t.id)?.last_engineer_action))}</div></div><div class="field"><label>Last QA testing</label><div class="code-line">${e(dateFmt(state.tasks.find(x=>x.id===t.id)?.last_qa_action))}</div></div></div><div class="form-actions"><label class="muted-note" style="align-self:center">Activity date <input type="date" id="status-work-date" value="${state.day}" class="date-input" style="margin-left:6px"></label><button class="btn" id="sync-pr" ${!canDev()?'disabled':''}>Sync PR</button>${canWrite()?'<button class="btn primary" id="save-task">Save changes</button>':''}</div>
 ${canWrite()?`<div class="panel-section"><h3>Log work / QA testing</h3><p class="subnote">Add an actual dated work entry. This will appear automatically in Daily Work.</p><div class="form-row wide">${inputSelect('Action type','activity-action','QA Testing',canDev()?state.statuses.actions:state.statuses.actions.filter(x=>!['Development','PR','Merge','Deployment'].includes(x)))}<div class="field"><label>Work date</label><input id="activity-date" type="date" value="${state.day}"></div><div class="field"><label>Environment</label><select id="activity-env">${option(['—','Local','PR','Stage','Production'],'Stage')}</select></div></div><div class="form-row" style="margin-top:12px"><div class="field grow"><label>Result / summary</label><input id="activity-result" list="outcome-options" placeholder="e.g. No Visible Changes, Passed, Fixed locally"><datalist id="outcome-options">${[...state.statuses.qa,...state.statuses.development].map(v=>`<option value="${e(v)}"></option>`).join('')}</datalist><div class="help">For QA Testing, selecting a standard result also updates the QA status automatically.</div></div></div><div class="field" style="margin-top:12px"><label>Detailed notes / evidence</label><textarea id="activity-notes" placeholder="What did you test or change? What happened? What needs to happen next?"></textarea></div><div class="form-actions"><button class="btn primary" id="add-activity">+ Add activity</button></div></div>`:''}
 <div class="tabs"><button class="${state.detailTab==='timeline'?'on':''}" data-tab="timeline">Activity timeline (${d.activities.length})</button><button class="${state.detailTab==='comments'?'on':''}" data-tab="comments">Discussion (${d.comments.length})</button><button class="${state.detailTab==='files'?'on':''}" data-tab="files">Attachments (${d.attachments.length})</button></div>
 <div id="detail-tab-content">${state.detailTab==='timeline'?`<div class="timeline">${activity||empty('No activity','Work entries will appear here.')}</div>`:state.detailTab==='comments'?`${discussion||empty('No discussion yet','Keep the conversation on this task.')}${canWrite()?'<div class="reply"><textarea id="comment-body" placeholder="Reply about this task..."></textarea><button class="btn primary" id="add-comment">Reply</button></div>':''}`:`<div class="muted-note">Upload screenshots or files that do not contain patient information or payment-card data.</div><div class="attachments-list">${d.attachments.map(a=>`<button class="attachment-link" data-download="${e(a.id)}" data-filename="${e(a.filename)}">${a.content_type.startsWith('image/')?`<img class="attachment-preview" src="/api/attachments/${e(a.id)}?preview=1" alt="${e(a.filename)}">`:''} ${e(a.filename)} (${Math.ceil(a.byte_size/1024)} KB)</button>`).join('')||'<span class="empty-line">No attachments</span>'}</div>${canWrite()?'<div style="margin-top:16px"><input type="file" id="file-input" accept="image/*,.pdf,.txt,.csv"/> <button class="btn" id="upload-file">Upload</button><p class="muted-note">Paste an image here with Ctrl/Cmd + V.</p><div id="image-paste-zone" tabindex="0" class="paste-zone">Click here, then paste a screenshot</div></div>':''}`}</div>
 <p class="muted-note" style="margin-top:24px">Changes to task status create additional dated activities. Existing timeline entries and comments are never edited or replaced.</p></div>`;
}
function changeTab(t){state.detailTab=t;renderDetail(state.detailData)}
function modal(kind){editingOfficeId=null;let markup='',title='';
 if(kind==='task'){
  title='New task / feature request';markup=`<div class="field"><label>Task title *</label><input id="new-title" placeholder="e.g. Outstanding Balance — new report" autofocus></div><div class="form-row">${inputSelect('Type','new-type','New Feature',state.statuses.types)}${inputSelect('Priority','new-priority','Medium',state.statuses.priorities)}</div><div class="form-row"><div class="field"><label>Category</label><select id="new-category">${option(state.statuses.categories,'General')}</select></div><div class="field"><label>Parent task (optional)</label><select id="new-parent"><option value="">No parent task</option>${state.tasks.map(t=>`<option value="${e(t.id)}">${e(t.title)}</option>`).join('')}</select></div></div><div class="field"><label>Requirements / reproduction steps</label><textarea id="new-description" placeholder="What should change? Expected behavior, actual behavior and acceptance criteria..."></textarea></div><div class="form-row"><div class="field"><label>Assignee (email, optional)</label><input id="new-assignee" placeholder="sean@example.com"></div><div class="field"><label>Next action owner (optional)</label><input id="new-next-owner" placeholder=""></div></div>`;
 }else if(kind==='office'){
  title='Log private daily work';markup=`<div class="report-intro">Only you and the boss can view this entry. It does not need to be linked to the Engineering Board.</div><div class="field"><label>Work title *</label><input id="office-title" placeholder="e.g. Ordered clinic supplies"></div><div class="form-row"><div class="field"><label>Work date</label><input type="date" id="office-date" value="${state.day}"></div><div class="field"><label>Category</label><select id="office-category">${option(['Work','Meeting','Other'],'Work')}</select></div><div class="field"><label>Status</label><select id="office-status">${option(['Completed','In Progress','Waiting','Blocked'],'Completed')}</select></div></div><div class="field"><label>Private project / task (optional)</label><select id="office-item"><option value="">Standalone activity</option>${state.privateItems.filter(i=>i.owner_email===state.user.email).map(i=>`<option value="${e(i.id)}">${e(i.kind)} · ${e(i.title)}</option>`).join('')}</select></div><div class="field"><label>Details</label><textarea id="office-details" placeholder="What was done today? Any next steps?"></textarea></div>`;
 }else if(kind==='user'){
  title='Add or update team member';markup=`<div class="field"><label>Email address (login account)</label><input id="user-email" type="email" placeholder="teammate@example.com"></div><div class="field"><label>Display name</label><input id="user-name" placeholder="Teammate"></div><div class="field"><label>Role</label><select id="user-role">${option(['admin','member'],'member')}</select></div><div class="field"><label>Work groups</label><div class="work-group-options">${['Engineering','QA','Management'].map(g=>`<label class="work-group-option"><input type="checkbox" name="user-group" value="${g}"><span>${g==='Management'?'Manager':g}</span></label>`).join('')}</div></div><div class="report-intro">Engineering and QA are independent of system role. Management provides the Manager overview and access to all Daily Work. Set a password after saving.</div>`;
 }
 $('#modal-content').innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="close" data-close="modal">×</button></div>${markup}<div class="form-actions"><button class="btn" data-close="modal">Cancel</button><button class="btn primary" data-save-modal="${kind}">Save ${kind==='task'?'task':'record'}</button></div>`;
 $('#modal-shade').classList.remove('hidden');
}
function closeModal(){$('#modal-shade').classList.add('hidden')}
async function saveModal(kind){
 if(kind==='task'){
 const p={title:$('#new-title').value,type:document.querySelector('[data-key="new-type"]').value,priority:document.querySelector('[data-key="new-priority"]').value,category:$('#new-category').value,parent_task_id:$('#new-parent').value,description:$('#new-description').value,assignee:$('#new-assignee').value,next_action_owner:$('#new-next-owner').value,activity_date:state.day};
 const d=await api('/tasks',{method:'POST',body:JSON.stringify(p)});closeModal();await reload();showToast('New task created');await openDetail(d.id);
 }else if(kind==='office'){
 const p={title:$('#office-title').value,work_date:$('#office-date').value,category:$('#office-category').value,status:$('#office-status').value,details:$('#office-details').value,work_item_id:$('#office-item').value};await api('/office'+(editingOfficeId?'/'+editingOfficeId:''),{method:editingOfficeId?'PATCH':'POST',body:JSON.stringify(p)});closeModal();await reload();showToast('Private daily work saved');
 }else if(kind==='user'){
 await api('/users',{method:'POST',body:JSON.stringify({email:$('#user-email').value,display_name:$('#user-name').value,role:$('#user-role').value,groups:[...document.querySelectorAll('[name="user-group"]:checked')].map(x=>x.value),is_boss:!!document.querySelector('[name="user-group"][value="Management"]:checked')})});closeModal();await reload();showToast('Team member saved');
 }
}
async function saveTask(){const t=state.detailData.task,patch={activity_date:$('#status-work-date').value};for(const f of document.querySelectorAll('.task-field')){const k=f.dataset.key;if(f.value!==String(t[k]??''))patch[k]=f.value;}if(Object.keys(patch).length===1){showToast('No changes to save');return}await api('/tasks/'+t.id,{method:'PATCH',body:JSON.stringify(patch)});await reload();showToast('Task changes recorded in timeline')}
async function addActivity(){const kind=document.querySelector('[data-key="activity-action"]').value;await api('/tasks/'+state.detail,{method:'POST',body:JSON.stringify({action_type:kind,activity_date:$('#activity-date').value,environment:$('#activity-env').value,result:$('#activity-result').value,notes:$('#activity-notes').value})});await reload();showToast('Work activity saved')}
async function addComment(){await api('/tasks/'+state.detail+'/comments',{method:'POST',body:JSON.stringify({body:$('#comment-body').value})});await reload();changeTab('comments');showToast('Reply posted')}
async function uploadFile(pastedFile){const file=pastedFile instanceof File?pastedFile:$('#file-input').files[0];if(!file)throw new Error('Select a file');const form=new FormData();form.append('file',file);form.append('task_id',state.detail);await api('/attachments',{method:'POST',body:form});await reload();changeTab('files');showToast('Attachment uploaded')}
async function syncPR(){const d=await api('/tasks/'+state.detail+'/sync-pr',{method:'POST'});await reload();showToast('GitHub: '+d.status)}
async function downloadFile(id,filename){
 const h={};if(state.local)h['x-dev-user']=$('#demo-user').value;
 const resp=await fetch('/api/attachments/'+encodeURIComponent(id),{headers:h});if(!resp.ok)throw new Error('Unable to download attachment');
 const blob=await resp.blob(),url=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=url;anchor.download=filename||'attachment';anchor.click();setTimeout(()=>URL.revokeObjectURL(url),3000);
}
async function downloadExport(){
 const h={};if(state.local)h['x-dev-user']=$('#demo-user').value;
 const resp=await fetch('/api/export',{headers:h});if(!resp.ok)throw new Error('Export permission denied');
 const blob=await resp.blob(),url=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=url;anchor.download='work-tracker-backup-'+state.day+'.json';anchor.click();setTimeout(()=>URL.revokeObjectURL(url),3000);
}
let filterTimer;
document.addEventListener('click',ev=>{
 const download=ev.target.closest('[data-download]');if(download)return busy(()=>downloadFile(download.dataset.download,download.dataset.filename));
 const open=ev.target.closest('[data-open]');if(open)return busy(()=>openDetail(open.dataset.open));
 const view=ev.target.closest('[data-view]');if(view)return setView(view.dataset.view);
 const mk=ev.target.closest('[data-modal]');if(mk)return modal(mk.dataset.modal);
 const close=ev.target.closest('[data-close]');if(close)return close.dataset.close==='detail'?closeDetail():closeModal();
 const tab=ev.target.closest('[data-tab]');if(tab)return changeTab(tab.dataset.tab);
 const sv=ev.target.closest('[data-save-modal]');if(sv)return busy(()=>saveModal(sv.dataset.saveModal));
 if(ev.target.id==='save-task')return busy(saveTask);
 if(ev.target.id==='add-activity')return busy(addActivity);
 if(ev.target.id==='add-comment')return busy(addComment);
 if(ev.target.id==='upload-file')return busy(uploadFile);
 if(ev.target.id==='sync-pr')return busy(syncPR);
 if(ev.target.id==='download-export')return busy(downloadExport);
});
document.addEventListener('change',ev=>{
 if(ev.target.matches('[data-day]'))return busy(async()=>{state.day=ev.target.value;state.summary=await api('/summary?date='+state.day);render();});
 if(ev.target.id==='daily-email'){state.dailyEmail=ev.target.value;return busy(loadDaily)}
 if(ev.target.id==='dev-filter'){state.devFilter=ev.target.value;render()}
 if(ev.target.id==='qa-filter'){state.qaFilter=ev.target.value;render()}
 if(ev.target.id==='category-filter'){state.categoryFilter=ev.target.value;render()}
 if(ev.target.id==='type-filter'){state.typeFilter=ev.target.value;render()}
 if(ev.target.id==='board-sort'){state.boardSort=ev.target.value==='Manual order'?'manual':ev.target.value==='Recently updated'?'recent':'priority';render()}
});
document.addEventListener('input',ev=>{if(ev.target.id==='task-search'||ev.target.id==='history-search'){state.filter=ev.target.value;clearTimeout(filterTimer);const id=ev.target.id;filterTimer=setTimeout(()=>{const pos=ev.target.selectionStart;render();const input=$('#'+id);if(input){input.focus();input.setSelectionRange(pos,pos)}},150)}});
$('#panel-shade').addEventListener('click',closeDetail);
$('#modal-shade').addEventListener('click',ev=>{if(ev.target.id==='modal-shade')closeModal()});
$('#refresh').addEventListener('click',()=>busy(reload));
$('#demo-user').addEventListener('change',()=>busy(async()=>{const d=await api('/me');state.user=d.user;state.filter='';state.dailyEmail='';state.view='dashboard';closeDetail();await reload();$('#account-profile').hidden=false;$('#login-entry').hidden=true;$('#nav').hidden=false;$('.top-actions').hidden=false;$('#current-user').textContent=state.user.display_name||who(state.user.email);$('#current-role').textContent=isBoss()?'Manager':(state.user.groups||[]).join(', ');$('#avatar').textContent=initial(who(state.user.email));$('#team-nav').hidden=!canManage();$('#history-nav').hidden=!canManage();document.querySelectorAll('#nav [data-view]').forEach(el=>el.classList.toggle('active',el.dataset.view==='dashboard'));$('#crumb').textContent='Dashboard';showToast('Previewing '+who(state.user.email))}));
function escapeError(v){return e(v)}
async function showLogin(){
 state.user=null;state.tasks=[];state.office=[];state.activities=[];state.users=[];state.summary=null;state.privateItems=[];releaseList=[];closeDetail();
 $('#account-profile').hidden=true;$('#login-entry').hidden=false;$('#nav').hidden=true;$('.top-actions').hidden=true;
 const status=await api('/auth/status');
 $('#content').innerHTML=`<div class="auth-card"><div class="eyebrow">WORK TRACKER</div><h1>${status.setupAvailable?'Set your password':'Sign in'}</h1><p class="subtitle">Use your Work Tracker email and password.</p><form id="login-form"><div class="field"><label for="login-email">Email</label><input id="login-email" type="email" autocomplete="username" value="${e(status.setupEmail||'')}" ${status.setupAvailable?'readonly':''} required></div><div class="field"><label for="login-password">Password</label><input id="login-password" type="password" autocomplete="${status.setupAvailable?'new-password':'current-password'}" ${status.setupAvailable?'minlength="12"':''} maxlength="256" required></div><p id="login-error" role="alert"></p><button class="btn primary" type="submit">${status.setupAvailable?'Set password and sign in':'Sign in'}</button></form>${status.setupAvailable?'<p class="muted-note">Choose at least 12 characters.</p>':''}</div>`;
 $('#login-form').onsubmit=async ev=>{ev.preventDefault();const btn=ev.target.querySelector('button');btn.disabled=true;$('#login-error').textContent='';try{await api(status.setupAvailable?'/auth/setup':'/auth/login',{method:'POST',body:JSON.stringify({email:$('#login-email').value,password:$('#login-password').value})});await load();}catch(error){$('#login-error').textContent=error.message;}finally{btn.disabled=false}};
}
$('#login-entry').onclick=()=>busy(showLogin);
$('#logout').onclick=()=>busy(async()=>{await api('/auth/logout',{method:'POST'});await showLogin()});
(async()=>{try{await load();}catch{await showLogin();}})();
const renderOrig=render;render=function(){renderOrig();if(state.view==='daily')busy(loadDaily)};

document.addEventListener('paste',ev=>{if(!state.detail||state.detailTab!=='files'||!canWrite())return;const files=[...(ev.clipboardData?.files||[])].filter(f=>f.type.startsWith('image/'));if(files.length){ev.preventDefault();busy(async()=>{for(const f of files)await uploadFile(f)})}});

document.addEventListener('click',ev=>{const button=ev.target.closest('[data-password-email]');if(!button)return;const email=button.dataset.passwordEmail;$('#modal-content').innerHTML=`<div class="modal-header"><h2>${state.users.find(u=>u.email===email)?.has_password?'Reset password':'Set password'}</h2><button class="close" data-close="modal">×</button></div><div class="modal-body"><p>${e(email)}</p><form id="member-password-form">${email===state.user.email?'<div class="field"><label>Current password</label><input id="current-password" type="password" autocomplete="current-password" required></div>':''}<div class="field"><label>Password (at least 12 characters)</label><input id="member-password" type="password" minlength="12" maxlength="256" autocomplete="new-password" required></div><button class="btn primary" type="submit">Save password</button></form></div>`;$('#modal-shade').classList.remove('hidden');$('#member-password-form').onsubmit=ev=>{ev.preventDefault();busy(async()=>{await api('/password',{method:'POST',body:JSON.stringify({email,password:$('#member-password').value,current_password:$('#current-password')?.value})});closeModal();if(email===state.user.email){await showLogin();showToast('Password updated. Sign in again.')}else{await reload();showToast('Password saved. Share it privately with this member.')}})};});

document.addEventListener("change",ev=>{if(ev.target.matches('[name="user-group"][value="Management"]')){const roleInput=$("#user-role");roleInput.value="member";roleInput.disabled=ev.target.checked;}});
let releaseList=[],selectedRelease='';
async function loadReleases(){if(canDev())await api('/releases/ensure',{method:'POST'});const d=await api('/releases');releaseList=d.releases;if(state.view!=='releases')return;if(!releaseList.some(r=>r.id===selectedRelease))selectedRelease=releaseList.find(r=>r.status==='Planned')?.id||releaseList[0]?.id||'';renderReleases()}
function renderReleases(){
 const root=$('#release-results');if(!root)return;const r=releaseList.find(x=>x.id===selectedRelease);
 const upcoming=releaseList.filter(x=>x.status==='Planned').sort((a,b)=>a.planned_date.localeCompare(b.planned_date));
 root.innerHTML=`<div class="release-toolbar"><span class="muted-note">The next Wednesday version is planned automatically. A new plan opens after actual release.</span><span class="muted-note">${upcoming.map((x,i)=>`${i===0?'Next release':i===1?'Following release':'Planned'}: ${e(x.version)} · ${e(dateFmt(x.planned_date))}`).join(' &nbsp; / &nbsp; ')||'No upcoming versions planned'}</span></div><div class="release-layout"><section class="card"><div class="card-head"><h2 class="card-title">Versions</h2></div>${releaseList.map(x=>`<button class="release-choice ${x.id===selectedRelease?'selected':''}" data-release="${e(x.id)}"><strong>${e(x.version)}</strong>${badge(x.status)}<span class="muted">${e(dateFmt(x.released_date||x.planned_date))}</span></button>`).join('')||empty('No versions yet','Plan the next Wednesday release to begin.')}</section><section class="card" id="release-detail">${r?releaseDetail(r):empty('Plan a version','Select Engineering Board tasks to build a release plan.')}</section></div>`;
 root.querySelectorAll('[data-release]').forEach(b=>b.onclick=()=>{selectedRelease=b.dataset.release;renderReleases()});
 $('#release-save')?.addEventListener('click',()=>busy(()=>saveRelease(false)));
 $('#release-publish')?.addEventListener('click',()=>busy(()=>saveRelease(true)));
}
function releaseDetail(r){const released=r.status==='Released',editable=canDev()&&!released,ids=JSON.parse(r.task_ids_json),items=released?JSON.parse(r.snapshot_json):state.tasks.filter(t=>ids.includes(t.id));const count=type=>items.filter(t=>t.type===type).length;
 const categories=['New Feature','Bug Fix','Improvement','UI/UX','Investigation'];
 return `<div class="card-head"><div><h2 class="card-title">${e(r.version)} ${badge(r.status)}</h2><p class="card-desc">${released?'Released '+e(dateFmt(r.released_date))+' · Historical snapshot':'Planned '+e(dateFmt(r.planned_date))+' · Estimates may change'}</p></div></div><div class="card-body">${r.auto_candidates?`<p class="muted-note">Automatically includes tasks moved to On Production after ${e(dateFmt(r.auto_start))}, through ${e(dateFmt(r.auto_end))}. Review before recording this release; uncheck and save to exclude. Future work can be selected manually.</p>`:''}<p>${count('New Feature')} new features · ${count('Bug Fix')} bug fixes · ${items.length} total changes</p>${categories.map(c=>{const ts=items.filter(t=>t.type===c);return ts.length?`<h3 class="release-category">${e(c)} (${ts.length})</h3>${ts.map(t=>`<div class="list-row"><div class="title-cell" data-open="${e(t.id)}">${e(t.title)}<div class="muted">${e(t.project)}</div></div>${badge(t.development_status)}</div>`).join('')}`:''}).join('')||empty('No tasks selected','Add work from the Engineering Board below.')}<div class="field"><label>Release notes</label><textarea id="release-notes" ${editable?'':'disabled'}>${e(r.notes)}</textarea></div>${editable?`<div class="form-row"><div class="field"><label>Planned date</label><input id="release-planned" type="date" value="${e(r.planned_date)}"></div><div class="field"><label>Actual release date</label><input id="release-actual" type="date" value="${state.day}"></div></div><h3 class="release-category">Include Engineering Board tasks</h3><div class="release-task-picker">${state.tasks.map(t=>`<label class="release-task-option"><input type="checkbox" name="release-task" value="${e(t.id)}" ${ids.includes(t.id)?'checked':''}><span>${e(t.title)}<small>${r.auto_candidates?.includes(t.id)?'Auto · ':''}${e(t.type)} · ${e(t.development_status)} · QA: ${e(t.qa_status)}</small></span></label>`).join('')||'<p>No Engineering Board tasks yet.</p>'}</div><p class="muted-note">Save the plan at any stage. Record a released version only after selected tasks are On Production or Closed. This records the release; it does not deploy CRM code. Released records are locked.</p><div class="form-actions"><button class="btn" id="release-save">Save plan</button><button class="btn primary" id="release-publish">Confirm actual release</button></div>`:''}</div>`;
}
async function saveRelease(publish){const body={task_ids:[...document.querySelectorAll('[name="release-task"]:checked')].map(x=>x.value),notes:$('#release-notes').value,planned_date:$('#release-planned').value,publish,released_date:$('#release-actual').value};await api('/releases/'+selectedRelease,{method:'PATCH',body:JSON.stringify(body)});await loadReleases();showToast(publish?'Release recorded and locked':'Release plan saved')}

document.addEventListener('click',ev=>{const button=ev.target.closest('[data-edit-user]');if(!button||!canManage())return;const u=state.users.find(x=>x.email===button.dataset.editUser);if(!u)return;modal('user');$('#modal-content h2').textContent='Edit team member';$('#user-email').value=u.email;$('#user-email').readOnly=true;$('#user-name').value=u.display_name;$('#user-role').value=u.role;const groups=JSON.parse(u.groups_json||'[]');document.querySelectorAll('[name="user-group"]').forEach(x=>x.checked=groups.includes(x.value));$('#user-role').disabled=groups.includes('Management');const note=$('#modal-content .report-intro');note.textContent='Update name, role and work groups. Saving these changes preserves the existing password.';const wrap=document.createElement('div');wrap.className='form-actions';{const b=document.createElement('button');b.className='btn';b.dataset.passwordEmail=u.email;b.textContent=u.has_password?'Reset password':'Set password';wrap.append(b);note.after(wrap);}});

async function loadManagerOverview(){
 const day=state.day;const [daily,engineering,versions]=await Promise.all([api('/daily?scope=team&date='+day),api('/engineering-daily?date='+day),api('/releases')]);
 if(state.view!=='dashboard'||!isBoss()||day!==state.day)return;
 const root=$('#manager-results');if(!root)return;
 const events=[...daily.activities.map(a=>({person:a.actor_email,title:a.task_title,id:a.task_id,status:a.result,notes:a.notes,time:a.created_at})),...daily.office.map(a=>({person:a.owner_email,title:a.title,status:a.status,notes:a.details,time:a.created_at}))].sort((a,b)=>b.time.localeCompare(a.time));
 const personRows=events.map(a=>`<tr><td>${e(who(a.person))}</td><td>${a.id?`<div class="title-cell" data-open="${e(a.id)}">${e(a.title)}</div>`:e(a.title)}</td><td>${e(a.status||'—')}</td><td class="work-notes">${e(a.notes||'—')}</td></tr>`).join('');
 const upcoming=versions.releases.filter(r=>r.status==='Planned').sort((a,b)=>a.planned_date.localeCompare(b.planned_date));
 const releaseRows=upcoming.slice(0,2).map((r,i)=>{const ids=JSON.parse(r.task_ids_json),tasks=state.tasks.filter(t=>ids.includes(t.id));return `<div class="list-row"><div class="list-main"><div class="eyebrow">${i===0?'NEXT RELEASE':'FOLLOWING RELEASE'}</div><div class="list-title">${e(r.version)} · ${e(dateFmt(r.planned_date))}</div><div class="list-meta">${tasks.filter(t=>t.type==='New Feature').length} new features · ${tasks.filter(t=>t.type==='Bug Fix').length} bug fixes · ${tasks.length} planned changes</div><div class="muted-note">${tasks.map(t=>e(t.title)).join(' · ')||'No tasks selected yet'}</div></div></div>`}).join('');
 const changes=engineering.activities.map(a=>`<tr><td>${e(who(a.actor_email))}</td><td><div class="title-cell" data-open="${e(a.task_id)}">${e(a.task_title)}</div></td><td>${badge(a.action_type)}</td><td>${e(a.result||'—')}<div class="muted-note">${e(a.notes||'')}</div></td></tr>`).join('');
 root.innerHTML=`<section class="card"><div class="card-head"><div><h2 class="card-title">Everyone’s daily work</h2><p class="card-desc">${e(dateFmt(day))} · Shared task activity and personal daily entries</p></div><button class="btn tiny" data-view="daily">View Daily Work ↗</button></div><div class="table-wrap"><table class="table"><thead><tr><th>PERSON</th><th>ACTIVITY</th><th>RESULT</th><th>DETAILS</th></tr></thead><tbody>${personRows||'<tr><td colspan="4">No team members yet.</td></tr>'}</tbody></table></div></section><div class="section-gap"></div><section class="card"><div class="card-head"><div><h2 class="card-title">Engineering Board progress</h2><p class="card-desc">${e(dateFmt(day))}</p></div><div><button class="btn tiny" data-view="board">Board ↗</button></div></div><div class="table-wrap"><table class="table"><thead><tr><th>PERSON</th><th>TASK</th><th>ACTIVITY</th><th>UPDATE</th></tr></thead><tbody>${changes||'<tr><td colspan="4">No Engineering Board updates for this date.</td></tr>'}</tbody></table></div></section><div class="section-gap"></div><section class="card"><div class="card-head"><div><h2 class="card-title">Upcoming versions</h2><p class="card-desc">Expected features and fixes</p></div><button class="btn tiny" data-view="releases">Version Control ↗</button></div><div class="card-body">${releaseRows||empty('No upcoming versions','Engineering can create the next release plan.')}</div></section>`;
}
function parentTaskSelect(t){return `<div class="field"><label>Parent task (optional)</label><select class="task-field" data-key="parent_task_id" ${canQA()||canDev()?'':'disabled'}><option value="">No parent task</option>${state.tasks.filter(p=>p.id!==t.id).map(p=>`<option value="${e(p.id)}" ${t.parent_task_id===p.id?'selected':''}>${e(p.title)}</option>`).join('')}</select></div>`}
async function loadBoardActivity(){const day=state.day,d=await api('/engineering-daily?date='+day);if(state.view!=='board'||day!==state.day)return;const root=$('#board-daily-results');if(!root)return;root.innerHTML=`<div class="table-wrap"><table class="table"><thead><tr><th>PERSON</th><th>TASK</th><th>ACTIVITY</th><th>DETAILS</th></tr></thead><tbody>${d.activities.map(a=>`<tr><td>${e(who(a.actor_email))}</td><td><div class="title-cell" data-open="${e(a.task_id)}">${e(a.task_title)}</div></td><td>${badge(a.action_type)}</td><td class="work-notes">${e(a.result)}<div class="muted-note">${e(a.notes||'')}</div></td></tr>`).join('')||'<tr><td colspan="4">No board activity for this date.</td></tr>'}</tbody></table></div>`}
function renderPrivateWork(){const root=$('#private-work-results');if(!root)return;
 const items=state.privateItems;
 const row=i=>`<div class="private-work-row"><div><strong>${e(i.title)}</strong> ${badge(i.status)}<div class="muted-note">${e(i.kind)}${isBoss()?' · '+e(who(i.owner_email)):''}</div>${i.description?`<p class="work-notes">${e(i.description)}</p>`:''}</div>${canWrite()&&i.owner_email===state.user.email?`<div class="private-actions"><button class="btn tiny" data-private-log="${e(i.id)}">Log activity</button><button class="btn tiny" data-private-edit="${e(i.id)}">Edit</button>${i.kind==='Project'?`<button class="btn tiny" data-private-child="${e(i.id)}">+ Task</button>`:''}</div>`:''}</div>`;
 const section=i=>`<div class="private-project">${row(i)}${items.filter(t=>t.parent_id===i.id).map(t=>`<div class="private-child">${row(t)}</div>`).join('')}</div>`;
 root.innerHTML=`<section class="card"><div class="card-head"><div><h2 class="card-title">Ongoing projects & tasks</h2><p class="card-desc">Continue the same work across days; log each day’s progress below.</p></div></div><div class="card-body">${items.filter(i=>!i.parent_id&&i.status!=='Completed').map(section).join('')||empty('No ongoing work','Create a private project or a small task.')}<details class="completed-work"><summary>Completed work</summary>${items.filter(i=>!i.parent_id&&i.status==='Completed').map(section).join('')||'<p class="muted-note">No completed projects or tasks.</p>'}</details></div></section>`;
}
let editingOfficeId=null;
async function editOffice(oid){const {office:o}=await api('/office/'+oid);modal('office');editingOfficeId=oid;$('#modal-content h2').textContent='Edit daily activity';$('#office-title').value=o.title;$('#office-date').value=o.work_date;$('#office-details').value=o.details;$('#office-status').value=o.status;const categories=$('#office-category');if(![...categories.options].some(x=>x.value===o.category))categories.add(new Option(o.category,o.category));categories.value=o.category;$('#office-item').value=o.work_item_id;}
function privateModal(iid='',parent=''){const i=state.privateItems.find(i=>i.id===iid);const projects=state.privateItems.filter(p=>p.kind==='Project'&&p.owner_email===state.user.email);
 $('#modal-content').innerHTML=`<div class="modal-head"><h2>${i?'Edit private '+i.kind.toLowerCase():'New private work'}</h2><button class="close" data-close="modal">×</button></div><form id="private-form"><div class="field"><label>Mode</label><select id="private-kind" ${i?'disabled':''}>${option(['Task','Project'],i?.kind||'Task')}</select></div><div class="field"><label>Title</label><input id="private-title" required maxlength="180" value="${e(i?.title)}" placeholder="e.g. Design Work Tracker"></div>${!i?`<div class="field" id="private-parent-field"><label>Project (optional)</label><select id="private-parent"><option value="">Standalone task</option>${projects.map(p=>`<option value="${e(p.id)}" ${parent===p.id?'selected':''}>${e(p.title)}</option>`).join('')}</select></div>`:''}<div class="field"><label>Description</label><textarea id="private-description">${e(i?.description)}</textarea></div>${i?`<div class="field"><label>Status</label><select id="private-status">${option(['In Progress','Waiting','Completed'],i.status)}</select></div>`:''}<div class="form-actions">${i?`<button class="btn" type="button" data-private-delete="${e(i.id)}">Delete</button>`:''}<button class="btn primary" type="submit">Save</button></div></form>`;
 $('#modal-shade').classList.remove('hidden');$('#private-kind').onchange=()=>{const f=$('#private-parent-field');if(f)f.hidden=$('#private-kind').value==='Project'};
 $('#private-form').onsubmit=ev=>{ev.preventDefault();busy(async()=>{await api('/private-work'+(i?'/'+i.id:''),{method:i?'PATCH':'POST',body:JSON.stringify({title:$('#private-title').value,description:$('#private-description').value,kind:$('#private-kind').value,parent_id:$('#private-kind').value==='Task'?$('#private-parent')?.value||'':'',status:$('#private-status')?.value})});closeModal();await loadDaily();showToast('Private work saved')})};
}
function confirmWorkDelete(path,title){$('#modal-content').innerHTML=`<div class="modal-head"><h2>Delete ${e(title)}?</h2><button class="close" data-close="modal">×</button></div><p>This removes it from your workspace. Its change record is retained.</p><div class="form-actions"><button class="btn" data-close="modal">Cancel</button><button class="btn primary" id="confirm-work-delete">Delete</button></div>`;$('#modal-shade').classList.remove('hidden');$('#confirm-work-delete').onclick=()=>busy(async()=>{await api(path,{method:'DELETE'});closeModal();await reload();showToast('Deleted')});}
document.addEventListener('click',ev=>{
 const add=ev.target.closest('[data-private-new]');if(add)return privateModal();
 const edit=ev.target.closest('[data-private-edit]');if(edit)return privateModal(edit.dataset.privateEdit);
 const child=ev.target.closest('[data-private-child]');if(child)return privateModal('',child.dataset.privateChild);
 const log=ev.target.closest('[data-private-log]');if(log){const i=state.privateItems.find(x=>x.id===log.dataset.privateLog);modal('office');$('#office-title').value=i.title;$('#office-item').value=i.id;return;}
 const oe=ev.target.closest('[data-office-edit]');if(oe)return busy(()=>editOffice(oe.dataset.officeEdit));
 const od=ev.target.closest('[data-office-delete]');if(od)return confirmWorkDelete('/office/'+od.dataset.officeDelete,'daily activity');
 const pd=ev.target.closest('[data-private-delete]');if(pd)return confirmWorkDelete('/private-work/'+pd.dataset.privateDelete,'private work');
});
